// The Pi vectors of pi-coding-agent's theme, keybinding-hint and visual-truncation helpers: what the pinned package's own functions return
// (test/parity/sdk-vectors/pi-coding-agent/<export>.json, generated by automation/gen/generate-sdk-vectors.mjs). Every case of every file is run. A case that
// needs the global theme or keybindings carries the palette and the table Pi ran with, which the test installs before it calls the SDK's own function.
type piCase struct {
	Name   string
	Args   []any
	Result json.RawMessage
	Throws *string
}

func loadPiCoding(t *testing.T, export string) []piCase {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("..", "..", "test", "parity", "sdk-vectors", "pi-coding-agent", export+".json"))
	if err != nil {
		t.Fatal(err)
	}
	var f struct{ Cases []piCase }
	if err := json.Unmarshal(raw, &f); err != nil {
		t.Fatal(err)
	}
	if len(f.Cases) == 0 {
		t.Fatalf("%s has no cases", export)
	}
	return f.Cases
}

func isUndefinedArg(v any) bool { m, ok := v.(map[string]any); return ok && m["$"] == "undefined" }

// installPalette makes the palette Pi ran with the host's theme, as the host publishes it.
func installPalette(t *testing.T, raw json.RawMessage) UITheme {
	t.Helper()
	theme, ok := decodeUITheme(raw)
	if !ok {
		t.Fatalf("palette %s does not decode", raw)
	}
	installedTheme.Store(nil)
	hostTheme.Store(nil)
	setHostTheme(theme, raw)
	return theme
}

func stylesOf(theme MarkdownTheme) map[string]func(string) string {
	return map[string]func(string) string{
		"heading": theme.Heading, "link": theme.Link, "linkUrl": theme.LinkUrl, "code": theme.Code, "codeBlock": theme.CodeBlock,
		"codeBlockBorder": theme.CodeBlockBorder, "quote": theme.Quote, "quoteBorder": theme.QuoteBorder, "hr": theme.Hr, "listBullet": theme.ListBullet,
		"bold": theme.Bold, "italic": theme.Italic, "underline": theme.Underline, "strikethrough": theme.Strikethrough,
	}
}

type themeResult struct {
	Palette json.RawMessage
	Keys    []string
	Styles  map[string]json.RawMessage
}

func expectStrings(t *testing.T, name, key string, raw json.RawMessage, got func(i int) string) {
	t.Helper()
	var want []string
	if err := json.Unmarshal(raw, &want); err != nil {
		t.Fatalf("%s %s: %v", name, key, err)
	}
	for i, w := range want {
		if g := got(i); g != w {
			t.Errorf("%s %s[%d] = %q, Pi %q", name, key, i, g, w)
		}
	}
}

var piSamples = func() []string {
	// The samples of automation/gen/sdk-vector-lib/theme-state.mjs; the vector's styles list one result per sample, in this order.
	return []string{"", "x", "to do it", "a\nb", "漢字", "\x1b[1m", "  ", "line\x1b[22m with close", "\x1b[3mi\x1b[23m", "multi\nline\x1b[1m\nbold", "a\r\nb", "\n"}
}()

func TestGetMarkdownThemeMatchesPi(t *testing.T) {
	for _, c := range loadPiCoding(t, "getMarkdownTheme") {
		var r themeResult
		if err := json.Unmarshal(c.Result, &r); err != nil {
			t.Fatal(err)
		}
		installPalette(t, r.Palette)
		theme := GetMarkdownTheme()
		for key, style := range stylesOf(theme) {
			raw, ok := r.Styles[key]
			if !ok {
				t.Errorf("%s: Pi's markdown theme has no %q", c.Name, key)
				continue
			}
			expectStrings(t, c.Name, key, raw, func(i int) string { return style(piSamples[i]) })
		}
		if len(r.Styles) != len(stylesOf(theme)) || len(r.Keys) != len(stylesOf(theme))+1 {
			t.Errorf("%s: Pi's markdown theme has %v, the SDK's has %d styles and highlightCode", c.Name, r.Keys, len(stylesOf(theme)))
		}
	}
}

func TestGetSelectListThemeMatchesPi(t *testing.T) {
	for _, c := range loadPiCoding(t, "getSelectListTheme") {
		var r themeResult
		if err := json.Unmarshal(c.Result, &r); err != nil {
			t.Fatal(err)
		}
		installPalette(t, r.Palette)
		theme := GetSelectListTheme()
		styles := map[string]func(string) string{"selectedPrefix": theme.SelectedPrefix, "selectedText": theme.SelectedText, "description": theme.Description, "scrollInfo": theme.ScrollInfo, "noMatch": theme.NoMatch}
		if len(r.Styles) != len(styles) {
			t.Errorf("%s: Pi's select list theme has %v", c.Name, r.Keys)
		}
		for key, style := range styles {
			expectStrings(t, c.Name, key, r.Styles[key], func(i int) string { return style(piSamples[i]) })
		}
		// getEditorTheme is the select list theme and the border color; Pi's own result is the select list's, so the editor's is checked against the same palette.
		editor := GetEditorTheme()
		if got, want := editor.BorderColor("x"), currentHostTheme().Fg("borderMuted", "x"); got != want {
			t.Errorf("%s: editor border = %q, want %q", c.Name, got, want)
		}
		if got, want := editor.SelectList.SelectedText("x"), theme.SelectedText("x"); got != want {
			t.Errorf("%s: editor select list = %q, want %q", c.Name, got, want)
		}
	}
}

func TestGetSettingsListThemeMatchesPi(t *testing.T) {
	for _, c := range loadPiCoding(t, "getSettingsListTheme") {
		var r struct {
			Palette json.RawMessage
			Keys    []string
			Styles  map[string]json.RawMessage
		}
		if err := json.Unmarshal(c.Result, &r); err != nil {
			t.Fatal(err)
		}
		installPalette(t, r.Palette)
		theme := GetSettingsListTheme()
		var cursor string
		if err := json.Unmarshal(r.Styles["cursor"], &cursor); err != nil || theme.Cursor != cursor {
			t.Errorf("%s: cursor = %q, Pi %q", c.Name, theme.Cursor, cursor)
		}
		for key, style := range map[string]func(string) string{"description": theme.Description, "hint": theme.Hint} {
			expectStrings(t, c.Name, key, r.Styles[key], func(i int) string { return style(piSamples[i]) })
		}
		for key, style := range map[string]func(string, bool) string{"label": theme.Label, "value": theme.Value} {
			var want [][2]string
			if err := json.Unmarshal(r.Styles[key], &want); err != nil {
				t.Fatal(err)
			}
			for i, w := range want {
				if g := [2]string{style(piSamples[i], false), style(piSamples[i], true)}; g != w {
					t.Errorf("%s %s[%d] = %q, Pi %q", c.Name, key, i, g, w)
				}
			}
		}
		if len(r.Keys) != 5 {
			t.Errorf("%s: Pi's settings list theme has %v", c.Name, r.Keys)
		}
	}
}

// highlightCode asks the host, so this test stands in for it: it answers the call with the lines Pi returned for the code and language of the call it
// received, and fails on a call that differs from the one Pi's case made (the theme it draws with is the palette installTheme installed or none).
func TestHighlightCodeAsksTheHostLikePi(t *testing.T) {
	cases := loadPiCoding(t, "highlightCode")
	type call struct {
		code, lang string
		markdown   bool
		palette    string
	}
	var seen []call
	answers := map[string][]string{}
	for _, c := range cases {
		var r struct {
			Palette json.RawMessage
			Lines   []string
		}
		if err := json.Unmarshal(c.Result, &r); err != nil {
			t.Fatal(err)
		}
		lang, _ := c.Args[1].(string)
		answers[fmt.Sprint(c.Args[0], "\x00", lang, "\x00", string(r.Palette))] = r.Lines
	}
	SetHostHelpers(&HostHelpers{HighlightCode: func(code, lang string, markdown bool, palette []byte) ([]string, error) {
		seen = append(seen, call{code, lang, markdown, string(palette)})
		return []string{"host:" + code}, nil
	}})
	t.Cleanup(func() { SetHostHelpers(nil) })
	for _, c := range cases {
		var r struct {
			Palette json.RawMessage
			Lines   []string
		}
		_ = json.Unmarshal(c.Result, &r)
		installPalette(t, r.Palette)
		code, _ := c.Args[0].(string)
		lang, _ := c.Args[1].(string)
		seen = nil
		got := HighlightCode(code, lang)
		if lang == "" {
			// Pi highlights nothing without a language: the code in the mdCodeBlock color, the host asked nothing.
			if len(seen) != 0 || !reflect.DeepEqual(got, r.Lines) {
				t.Errorf("%s: HighlightCode(%q, none) = %q (host asked %d times), Pi %q", c.Name, code, got, len(seen), r.Lines)
			}
			continue
		}
		if len(seen) != 1 || seen[0].code != code || seen[0].lang != lang || seen[0].markdown || seen[0].palette != "" {
			t.Errorf("%s: the host was asked %+v", c.Name, seen)
		}
		if !reflect.DeepEqual(got, []string{"host:" + code}) {
			t.Errorf("%s: HighlightCode returned %q, not the host's lines", c.Name, got)
		}
	}
}

func TestInitThemeInstallsTheHostsTheme(t *testing.T) {
	for _, c := range loadPiCoding(t, "initTheme") {
		var r struct {
			Name    string
			Palette json.RawMessage
			Fg      []string
			Bold    []string
		}
		if err := json.Unmarshal(c.Result, &r); err != nil {
			t.Fatal(err)
		}
		if len(r.Palette) == 0 {
			continue // the system theme is generated from the terminal's colors: only the host knows it
		}
		hostTheme.Store(nil)
		installedTheme.Store(nil)
		SetHostHelpers(&HostHelpers{LoadTheme: func(name *string) ([]byte, error) {
			want, _ := c.Args[0].(string)
			if name == nil || *name != want {
				t.Errorf("%s: the host was asked for %v", c.Name, name)
			}
			return r.Palette, nil
		}})
		name, _ := c.Args[0].(string)
		if err := InitTheme(name); err != nil {
			t.Fatalf("%s: %v", c.Name, err)
		}
		theme := currentHostTheme()
		for i, sample := range piSamples {
			if got := theme.Fg("accent", sample); got != r.Fg[i] {
				t.Errorf("%s: fg(accent, %q) = %q, Pi %q", c.Name, sample, got, r.Fg[i])
			}
			if got := theme.Bold(sample); got != r.Bold[i] {
				t.Errorf("%s: bold(%q) = %q, Pi %q", c.Name, sample, got, r.Bold[i])
			}
		}
		if string(installedThemePalette()) != string(r.Palette) {
			t.Errorf("%s: the installed palette is not the one the host answered", c.Name)
		}
		SetHostHelpers(nil)
	}
}

// The installed theme stands until the host's own theme changes, and a state snapshot that repeats the host's palette leaves it.
func TestInstalledThemeLastsUntilTheHostsThemeChanges(t *testing.T) {
	hostTheme.Store(nil)
	installedTheme.Store(nil)
	dark := json.RawMessage(`{"name":"dark","foregrounds":{"accent":"<dark>"},"backgrounds":{}}`)
	light := json.RawMessage(`{"name":"light","foregrounds":{"accent":"<light>"},"backgrounds":{}}`)
	other := json.RawMessage(`{"name":"other","foregrounds":{"accent":"<other>"},"backgrounds":{}}`)
	decode := func(raw json.RawMessage) UITheme { theme, _ := decodeUITheme(raw); return theme }
	setHostTheme(decode(dark), dark)
	SetHostHelpers(&HostHelpers{LoadTheme: func(*string) ([]byte, error) { return other, nil }})
	t.Cleanup(func() { SetHostHelpers(nil); installedTheme.Store(nil) })
	if err := InitTheme("other"); err != nil {
		t.Fatal(err)
	}
	setHostTheme(decode(dark), dark)
	if got := currentHostTheme().Fg("accent", "x"); got != "<other>x\x1b[39m" {
		t.Fatalf("a repeated host palette replaced the installed theme: %q", got)
	}
	setHostTheme(decode(light), light)
	if got := currentHostTheme().Fg("accent", "x"); got != "<light>x\x1b[39m" {
		t.Fatalf("a changed host palette left the installed theme: %q", got)
	}
}

func TestTruncateToVisualLinesMatchesPi(t *testing.T) {
	for _, c := range loadPiCoding(t, "truncateToVisualLines") {
		text := c.Args[0].(string)
		max, width := int(c.Args[1].(float64)), 0
		width = int(c.Args[2].(float64))
		var options []VisualTruncateOption
		if len(c.Args) > 3 && !isUndefinedArg(c.Args[3]) {
			options = append(options, WithVisualPaddingX(int(c.Args[3].(float64))))
		}
		if len(c.Args) > 4 && !isUndefinedArg(c.Args[4]) {
			options = append(options, WithVisualKeep(c.Args[4].(string)))
		}
		var want struct {
			VisualLines  []string
			SkippedCount int
		}
		if err := json.Unmarshal(c.Result, &want); err != nil {
			t.Fatal(err)
		}
		got := TruncateToVisualLines(text, max, width, options...)
		if !reflect.DeepEqual(got.VisualLines, want.VisualLines) || got.SkippedCount != want.SkippedCount {
			t.Errorf("%s: %+v, Pi %+v", c.Name, got, want)
		}
	}
}

// installKeybindings makes the table Pi ran with pi-tui's global keybindings, as the host publishes it.
func installKeybindings(t *testing.T, defs map[string]struct {
	DefaultKeys json.RawMessage
	Description string
}, user map[string]json.RawMessage) {
	t.Helper()
	definitions := tui.KeybindingDefinitions{}
	for id, def := range defs {
		definitions[id] = tui.KeybindingDefinition{DefaultKeys: wireKeys(def.DefaultKeys), Description: def.Description}
	}
	overrides := tui.KeybindingsConfig{}
	for id, keys := range user {
		overrides[id] = wireKeys(keys)
	}
	tui.SetKeybindings(tui.NewKeybindingsManager(definitions, overrides))
}

type keyHintResult struct {
	Palette  json.RawMessage
	Platform string
	Defs     map[string]struct {
		DefaultKeys json.RawMessage
		Description string
	}
	User map[string]json.RawMessage
	Text string
}

// onPlatform runs fn with the platform key hints are written for set to a Pi process.platform value.
func onPlatform(t *testing.T, platform string, fn func()) {
	t.Helper()
	previous := keyHintGOOS
	keyHintGOOS = map[string]string{"darwin": "darwin", "linux": "linux", "win32": "windows"}[platform]
	defer func() { keyHintGOOS = previous }()
	fn()
}

func TestKeyTextMatchesPi(t *testing.T) {
	for _, c := range loadPiCoding(t, "keyText") {
		var r keyHintResult
		if err := json.Unmarshal(c.Result, &r); err != nil {
			t.Fatal(err)
		}
		installKeybindings(t, r.Defs, r.User)
		onPlatform(t, r.Platform, func() {
			if got := KeyText(c.Args[2].(string)); got != r.Text {
				t.Errorf("%s: KeyText = %q, Pi %q", c.Name, got, r.Text)
			}
		})
	}
}

